class Account {
  balance = 0; // field: an own property of each instance
  deposit(amount) { // method: one function on Account.prototype
    this.balance += amount;
  }
}
class SavingsAccount extends Account {}

const a = new Account();
const s = new SavingsAccount();
console.log(typeof Account); // function
console.log(Object.hasOwn(a, "balance")); // true
console.log(Object.hasOwn(a, "deposit")); // false
console.log(a.deposit === s.deposit); // true: one shared function
const parent = Object.getPrototypeOf(SavingsAccount.prototype);
console.log(parent === Account.prototype); // true

Account.prototype.close = function () { return "closed"; }; // added later
console.log(s.close()); // closed: found through the chain at call time

