class Button {
  handleClick() {
    console.log("Button: track click");
  }
}

class SubmitButton extends Button {
  handleClick() {
    super.handleClick();
    console.log("SubmitButton: submit form");
  }
}

const button = new SubmitButton();
const onClick = () => button.handleClick(); // keeps `this` for a listener
onClick();
// Button: track click
// SubmitButton: submit form
